app.get('/api/builds/:buildId/stream-logs', authenticate, async (req, res) => {
  const build = await BuildJob.findByPk(req.params.buildId, { include: ['project'] });
  if (!build || !build.project) return res.status(404).send('Build not found');
  const hasAccess = await ProjectMember.findOne({
    where: { projectId: build.projectId, userId: req.user.id }
  });
  if (!hasAccess) return res.status(403).send('Forbidden: no access to target build logs');

  res.setHeader('Content-Type', 'text/event-stream');
  res.setHeader('Cache-Control', 'no-cache');
  res.setHeader('Connection', 'keep-alive');

  const onLogChunk = (chunk) => {
    res.write(`data: ${JSON.stringify({ log: chunk })}\n\n`);
  };

  buildLogEmitter.on(`build:${req.params.buildId}`, onLogChunk);
  req.on('close', () => {
    buildLogEmitter.off(`build:${req.params.buildId}`, onLogChunk);
  });
});
